questionvariables.text:
/* Where Jack has nn more than Jill and Simon has mm less that Jill, valid question is given by product of Jack and Simon at most LL >= 2mm + 3nn + 6 (gives gap of at least £3 between higher root and mm) */
nn:rand(10)+1;
mm:rand_with_prohib(1,10,[nn,nn-1]);
LL:rand_with_prohib(ceiling((2*mm+3*nn+6)/10),3*ceiling((2*mm+3*nn+6)/10),[])*10;

/* Solutions */
tans1:x^2+(nn-mm-1)*x-nn*mm-LL;

tans3:floor(max(rhs(first(solve(tans1))),rhs(second(solve(tans1)))))+nn;

tans4: mm+nn+1;
/* (since Simon must have more that £0) */

feedbackvariables.text:
sansA: if ans2="<= 0" then ans1<=0 else if ans2=">= 0" then ans1>=0 else if ans2="< 0" then ans1<0 else ans1>0;
tansA: tans1<=0;

