/* Node 2: Worked solution */

/* Node 3: Check if expression is in correct apart from form (1) */

/* Node 4: Check correct expression with incorrect sign (1) */

/* Node 5: Check non-simplified expression with incorrect sign */

/* Node 6: Ignored the "more than" in forming their expression */

/* Node 7: Check correct symbol */

/* Node 1: Decide whether checking answers for correctness or consistency with incorrect (a) */
sansA: if ans2="<= 0" then ans1<=0 else if ans2=">= 0" then ans1>=0 else if ans2="< 0" then ans1<0 else ans1>0;
tansA: tans1<=0;

/* Node 2: Worked solution */

/* For Correct (a) */

/* Node 3: Check both answers correct */
node3_test: if ans3=tans3 and ans4=tans4 then 1 else 0;

/* Node 4: Check maximum correct (1) */

/* Node 5: Check maximum correct but unrounded */
node5_test: if float(ans3)=float(floor(10*max(rhs(first(solve(tans1))),rhs(second(solve(tans1)))))/10+nn) or float(ans3)=float(floor(100*max(rhs(first(solve(tans1))),rhs(second(solve(tans1)))))/100+nn) or float(ans3)=float(floor(1000*max(rhs(first(solve(tans1))),rhs(second(solve(tans1)))))/1000+nn) or float(ans3)=float(floor(10000*max(rhs(first(solve(tans1))),rhs(second(solve(tans1)))))/10000+nn) then 1 else 0;

/* Node 6: Check maximum correct but rounded up not down */
node6_test: if ans3=ceiling(max(rhs(first(solve(tans1))),rhs(second(solve(tans1)))))+nn or float(ans3)=float(ceiling(10*max(rhs(first(solve(tans1))),rhs(second(solve(tans1)))))/10+nn) or float(ans3)=float(ceiling(100*max(rhs(first(solve(tans1))),rhs(second(solve(tans1)))))/100+nn) or float(ans3)=float(ceiling(1000*max(rhs(first(solve(tans1))),rhs(second(solve(tans1)))))/1000+nn) or float(ans3)=float(ceiling(10000*max(rhs(first(solve(tans1))),rhs(second(solve(tans1)))))/10000+nn) then 1 else 0;

/* Node 7: Check maximum found for Jill / Simon */
node7_test: if ans3=floor(max(rhs(first(solve(tans1))),rhs(second(solve(tans1))))) or ans3=floor(max(rhs(first(solve(tans1))),rhs(second(solve(tans1)))))-mm then 1 else 0;

/* Node 8: Check minimum correct (2) */

/* Node 9: Check minimum not rounded up (ie Simon has £0) (1) */

/* Node 10: Check impossible minimum given (where Simon has negative money) (1) */
node10_test: if ans4=ceiling(min(rhs(first(solve(tans1))),rhs(second(solve(tans1)))))+nn or ans4=floor(min(rhs(first(solve(tans1))),rhs(second(solve(tans1)))))+nn or float(ans4)=float(ceiling(10*min(rhs(first(solve(tans1))),rhs(second(solve(tans1)))))/10+nn) or float(ans4)=float(floor(10*min(rhs(first(solve(tans1))),rhs(second(solve(tans1)))))/10+nn) or float(ans4)=float(ceiling(100*min(rhs(first(solve(tans1))),rhs(second(solve(tans1)))))/100+nn) or float(ans4)=float(floor(100*min(rhs(first(solve(tans1))),rhs(second(solve(tans1)))))/100+nn) then 1 else 0;

/* Node 11: Check minimum found for Jill / Simon */
node11_test: if ans4=1 or ans4=mm+1 then 1 else 0;

/* Node 12: Check impossible minimum found for Jill / Simon */
node12_test: if ans4=ceiling(min(rhs(first(solve(tans1))),rhs(second(solve(tans1))))) or ans4=floor(min(rhs(first(solve(tans1))),rhs(second(solve(tans1))))) or float(ans4)=float(ceiling(10*min(rhs(first(solve(tans1))),rhs(second(solve(tans1)))))/10) or float(ans4)=float(floor(10*min(rhs(first(solve(tans1))),rhs(second(solve(tans1)))))/10) or float(ans4)=float(ceiling(100*min(rhs(first(solve(tans1))),rhs(second(solve(tans1)))))/100) or float(ans4)=float(floor(100*min(rhs(first(solve(tans1))),rhs(second(solve(tans1)))))/100) or ans4=ceiling(min(rhs(first(solve(tans1))),rhs(second(solve(tans1)))))-mm or ans4=floor(min(rhs(first(solve(tans1))),rhs(second(solve(tans1)))))-mm or float(ans4)=float(ceiling(10*min(rhs(first(solve(tans1))),rhs(second(solve(tans1)))))/10-mm) or float(ans4)=float(floor(10*min(rhs(first(solve(tans1))),rhs(second(solve(tans1)))))/10-mm) or float(ans4)=float(ceiling(100*min(rhs(first(solve(tans1))),rhs(second(solve(tans1)))))/100-mm) or float(ans4)=float(floor(100*min(rhs(first(solve(tans1))),rhs(second(solve(tans1)))))/100-mm) then 1 else 0;
